import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十二卦 賁 山火賁 艮上離下","description":"周易 - 第二十二卦 賁 山火賁 艮上離下","frontmatter":{"title":"第二十二卦 賁 山火賁 艮上離下","description":"周易 - 第二十二卦 賁 山火賁 艮上離下"},"headers":[],"relativePath":"classics/zhouyi/023.md","filePath":"classics/zhouyi/023.md"}'),l={name:"classics/zhouyi/023.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="賁" tabindex="-1">賁 <a class="header-anchor" href="#賁" aria-label="Permalink to “賁”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。小利有所往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>賁，亨；柔來而文剛，故亨。分剛上而文柔，故小利有攸往。天文也；文明以止，人文也。觀乎天文，以察時變；觀乎人文，以化成天下。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山下有火，賁；君子以明庶政，無敢折獄。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>賁其趾，舍車而徒。象曰：舍 車而徒，義弗乘也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>賁其須。象曰：賁其須，與上興也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>賁如濡如，永貞吉。象曰：永貞之吉，終莫之陵也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>賁如皤如，白馬翰如，匪寇婚媾。象曰：六四，當位疑也。匪寇婚媾，終無尤也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>賁於丘園，束帛戔戔，吝，終吉。象曰：六五之吉，有喜也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>白賁，無咎。象曰：白賁無咎，上得志也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
